import type * as XLSX from 'xlsx';
import { loadXlsx, loadXlsxCalc } from './xlsx-loader';

export interface FormulaCalculationFailure {
  address: string;
  formula: string;
}

/**
 * Reads an Excel workbook and calculates formula cells in the browser.
 *
 * `sheetStubs` is required because SheetJS otherwise omits formula cells whose
 * cached result is empty (for example, files generated by openpyxl).
 */
export async function readCalculatedWorkbook(
  data: ArrayBuffer | Uint8Array,
): Promise<XLSX.WorkBook> {
  const [xlsx, xlsxCalc] = await Promise.all([loadXlsx(), loadXlsxCalc()]);
  const workbook = xlsx.read(data, {
    type: 'array',
    cellFormula: true,
    sheetStubs: true,
  });

  // Keep processing when an unrelated or unsupported formula is encountered.
  // Successfully supported formulas are still calculated and written to `v`.
  xlsxCalc.default(workbook, { continue_after_error: true });

  return workbook;
}

/**
 * Finds formula cells in a labelled column that will be converted to zero by
 * the summary process because their result is not a finite number.
 */
export async function findUncalculatedNumericFormulas(
  worksheet: XLSX.WorkSheet,
  columnLabel: string,
): Promise<FormulaCalculationFailure[]> {
  const xlsx = await loadXlsx();
  if (!worksheet['!ref']) {
    return [];
  }

  const range = xlsx.utils.decode_range(worksheet['!ref']);
  let targetColumn: number | undefined;

  for (let column = range.s.c; column <= range.e.c; column++) {
    const address = xlsx.utils.encode_cell({ r: range.s.r, c: column });
    if (worksheet[address]?.v === columnLabel) {
      targetColumn = column;
      break;
    }
  }

  if (targetColumn === undefined) {
    return [];
  }

  const failures: FormulaCalculationFailure[] = [];
  for (let row = range.s.r + 1; row <= range.e.r; row++) {
    const address = xlsx.utils.encode_cell({ r: row, c: targetColumn });
    const cell = worksheet[address];

    if (
      cell?.f
      && (
        cell.t === 'e'
        || cell.t === 'z'
        || !Number.isFinite(Number(cell.v))
      )
    ) {
      failures.push({ address, formula: cell.f });
    }
  }

  return failures;
}
